import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

@Controller('api/v1')
export class FnSfr03208Controller {
  @Post('/requisitions/:requisitionId/submit')
  @HttpCode(200)
  async submitRequisition(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const requisitionId = req.params['requisitionId'];
    if (!/^[0-9]+$/.test(requisitionId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '품의서 ID 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT requisition_id AS "requisitionId", status, title, content
           FROM requisition
          WHERE requisition_id = CAST(:requisitionId AS bigint)
          FOR UPDATE`,
        { requisitionId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'REQUISITION_NOT_FOUND', '품의서를 찾을 수 없습니다.');
      }
      const requisition = found[0];
      // 기안 상태에서만 상신할 수 있다.
      if (requisition.status !== '기안') {
        throw new ApiError(409, 'REQUISITION_NOT_EDITABLE', '기안 상태의 품의서만 상신할 수 있습니다.');
      }
      // 가정: S3 상신 문서의 결재양식은 사용 중인 첫 번째 결재양식으로 정한다.
      const forms = await db.query(
        `SELECT approval_form_id AS "approvalFormId"
           FROM approval_form
          WHERE use_status = '사용'
          ORDER BY approval_form_id
          LIMIT 1`,
        {},
      );
      if (forms.length === 0) {
        throw new ApiError(502, 'APPROVAL_LINK_FAILED', '전자결재 연계에 실패했습니다. 사용 중인 결재양식이 없습니다.');
      }
      // 가정: 문서번호는 품의서 ID와 상신 시각으로 만든다.
      const documents = await db.query(
        `INSERT INTO approval_document (
           document_no, approval_form_id, drafter_id, title, body,
           approval_status, submitted_at, created_at, updated_at
         ) VALUES (
           'REQ-' || CAST(:requisitionId AS text) || '-' || to_char(now(), 'YYYYMMDDHH24MISSMS'),
           CAST(:approvalFormId AS bigint),
           CAST(:userId AS bigint),
           :title,
           :content,
           '결재대기',
           now(),
           now(),
           now()
         )
         RETURNING approval_document_id AS "approvalDocumentId"`,
        {
          requisitionId,
          approvalFormId: forms[0].approvalFormId,
          userId: user.id,
          title: requisition.title,
          content: requisition.content,
        },
      );
      const approvalDocumentId = documents[0].approvalDocumentId;
      const changed = await db.execute(
        `UPDATE requisition
            SET status = '결재대기',
                approval_document_id = CAST(:approvalDocumentId AS bigint),
                updated_at = now()
          WHERE requisition_id = CAST(:requisitionId AS bigint)
            AND status = '기안'`,
        { requisitionId, approvalDocumentId },
      );
      if (changed === 0) {
        throw new ApiError(409, 'REQUISITION_NOT_EDITABLE', '기안 상태의 품의서만 상신할 수 있습니다.');
      }
      return { status: '결재대기', approvalDocumentId };
    });
  }
}

