import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  Select,
  TextInput,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr03208Page({ role, notify }: PageProps) {
  const [rows, setRows] = useState<Row[]>([]);
  const [statusFilter, setStatusFilter] = useState('');
  const [appliedStatus, setAppliedStatus] = useState('');
  const [creating, setCreating] = useState(false);
  const [target, setTarget] = useState<Row | null>(null);
  const [projectId, setProjectId] = useState<number | string>('');
  const [budgetAccountId, setBudgetAccountId] = useState<number | string>('');
  const [requisitionType, setRequisitionType] = useState('');
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [amount, setAmount] = useState<number | string>('');

  const visible = rows.filter((r) => appliedStatus === '' || r.status === appliedStatus);

  function resetForm() {
    setProjectId('');
    setBudgetAccountId('');
    setRequisitionType('');
    setTitle('');
    setContent('');
    setAmount('');
  }

  async function create() {
    if (projectId === '' || budgetAccountId === '' || requisitionType === '' || title.trim() === '' || amount === '') {
      throw new Error('프로젝트, 예산과목, 품의 유형, 품의 제목, 품의 금액을 모두 입력해 주세요.');
    }
    const res = await call<Row>('POST', '/requisitions', role, {
      projectId,
      budgetAccountId,
      requisitionType,
      title,
      content,
      requisitionAmount: amount,
    });
    setRows([
      {
        requisitionId: res.requisitionId,
        title,
        requisitionAmount: amount,
        status: res.status,
        approvalDocumentId: null,
      },
      ...rows,
    ]);
    setCreating(false);
    resetForm();
    notify('품의서를 저장했습니다.');
  }

  async function submit() {
    if (!target) return;
    const res = await call<Row>('POST', `/requisitions/${target.requisitionId}/submit`, role, {});
    setRows(
      rows.map((r) =>
        r.requisitionId === target.requisitionId
          ? { ...r, status: res.status, approvalDocumentId: res.approvalDocumentId }
          : r,
      ),
    );
    setTarget(null);
    notify('품의서를 상신했습니다.');
  }

  return (
    <div className='doc'>
      <section className='box'>
        <h2>지출품의서</h2>
        <Filters onSearch={() => setAppliedStatus(statusFilter)} onReset={() => { setStatusFilter(''); setAppliedStatus(''); }}>
          <Field label='처리 상태'>
            <Select
              value={statusFilter}
              onChange={setStatusFilter}
              placeholder='전체'
              options={[['기안', '기안'], ['결재대기', '결재대기']]}
            />
          </Field>
        </Filters>
        <Band total={visible.length}>
          <button onClick={() => setCreating(true)}>품의서 작성</button>
        </Band>
        <DataTable
          rows={visible}
          empty='아직 작성한 품의서가 없습니다. 품의서 작성 버튼으로 시작해 주세요.'
          columns={[
            { key: 'requisitionId', label: '품의서 ID' },
            { key: 'title', label: '품의 제목' },
            { key: 'requisitionAmount', label: '품의 금액', render: (r) => <Num value={r.requisitionAmount} /> },
            { key: 'status', label: '처리 상태', render: (r) => <Badge value={r.status} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) =>
                r.status === '기안' ? (
                  <button className='ghost' onClick={() => setTarget(r)}>상신</button>
                ) : null,
            },
          ]}
        />
      </section>
      {creating && (
        <Drawer title='품의서 작성' onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit='저장'>
            <Field label='프로젝트' required>
              <LookupSelect table='project' role={role} value={projectId} onChange={setProjectId} />
            </Field>
            <Field label='예산과목' required>
              <LookupSelect table='budget_account' role={role} value={budgetAccountId} onChange={setBudgetAccountId} />
            </Field>
            <Field label='품의 유형' required>
              <Select value={requisitionType} onChange={setRequisitionType} options={[['지출', '지출'], ['구매', '구매']]} />
            </Field>
            <Field label='품의 제목' required>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label='품의 금액' required>
              <NumberInput value={amount} onChange={setAmount} />
            </Field>
            <Field label='품의 내용' wide>
              <TextInput value={content} onChange={setContent} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
      {target && (
        <Drawer title='품의서 상신' onClose={() => setTarget(null)}>
          <Form
            onSubmit={submit}
            submit='상신'
            note={<p>상신하면 전자결재로 연계되고 상태가 결재대기로 바뀝니다. 승인된 뒤에는 임의로 수정할 수 없습니다.</p>}
          >
            <p>{String(target.title)} 품의서를 상신합니다.</p>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
